import UnitUtils from '../UnitUtils';
import Base from '../base';
// @ts-ignore
import { PolygonStyle } from '../interface';
import { Vector3 } from 'three';

export default class FreehandPolygon extends Base {
  points: Vector3[] = [];
  freehand: boolean;

  constructor(viewer: any, style?: PolygonStyle) {
    super(viewer, style);
    this.freehand = true;
    this.setState('drawing');
  }

  getType(): 'polygon' | 'line' {
    return 'polygon';
  }

  /**
   * Add points only on click events
   */
  addPoint(cartesian: Vector3) {
    UnitUtils.vectorScale(cartesian,30);
    this.points.push(cartesian);
    if (this.points.length === 1) {
      this.onMouseMove();
    } else if (this.points.length > 2) {
      this.finishDrawing();
    }
  }

  /**
   * Draw a shape based on mouse movement points during the initial drawing.
   */
  updateMovingPoint(cartesian: Vector3) {
    UnitUtils.vectorScale(cartesian,30);
    this.points.push(cartesian);
    if (this.points.length > 2) {
      this.setGeometryPoints(this.points);
      this.drawPolygon();
      this.eventDispatcher.dispatchEvent('drawUpdate', cartesian);
    }
  }

  /**
   * In edit mode, drag key points to update corresponding key point data.
   */
  updateDraggingPoint(cartesian: Vector3, index: number) {
    this.points[index] = cartesian;
    this.setGeometryPoints(this.points);
    this.drawPolygon();
  }

  getPoints() {
    return this.points;
  }
}
